import React, { useEffect, useRef } from 'react';

export const ParticleNetwork = () => {
  const canvasRef = useRef(null);

  useEffect(() => {
    const canvas = canvasRef.current;
    const ctx = canvas.getContext('2d');
    canvas.width = window.innerWidth;
    canvas.height = window.innerHeight;

    let particlesArray;
    // මවුස් එකේ බලපෑම ඇති වන රවුම (Radius)
    let mouse = { x: null, y: null, radius: 150 };

    window.addEventListener('mousemove', (e) => {
      mouse.x = e.x;
      mouse.y = e.y;
    });

    class Particle {
      constructor(x, y, dx, dy, size) {
        this.x = x;
        this.y = y;
        this.dx = dx; // සාමාන්‍ය වේගය X
        this.dy = dy; // සාමාන්‍ය වේගය Y
        this.size = size;
      }

      draw() {
        ctx.beginPath();
        ctx.arc(this.x, this.y, this.size, 0, Math.PI * 2, false);
        ctx.fillStyle = '#00ff88'; // Neon Green Dots
        ctx.fill();
      }

      update() {
        // Screen එකේ දාරවල වැදුනම හැරෙනවා
        if (this.x > canvas.width || this.x < 0) this.dx = -this.dx;
        if (this.y > canvas.height || this.y < 0) this.dy = -this.dy;
        
        let dx = mouse.x - this.x;
        let dy = mouse.y - this.y;
        let distance = Math.sqrt(dx * dx + dy * dy);
        
        // --- ✅ EXPLOSIVE SCATTERING LOGIC ---
        // මවුස් එක ළඟට ආවම ක්‍රියාත්මක වෙනවා
        if (distance < mouse.radius) {
            // මවුස් එකෙන් ඈතට තල්ලු විය යුතු දිශාව (Vector)
            const forceDirectionX = dx / distance;
            const forceDirectionY = dy / distance;
            
            // මවුස් එකට ලං වන තරමට තල්ලු වන බලය (Force) වැඩි වෙනවා
            const force = (mouse.radius - distance) / mouse.radius;
            
            // 🚀 SCATTER SPEED: මේ අංකය (35) වැඩි කළොත් තවත් වේගෙන් විසි වෙනවා
            const scatterSpeed = force * 5; 
            
            // තත්පරයෙන් තිත් ටික එහාට විසි කරනවා
            this.x -= forceDirectionX * scatterSpeed;
            this.y -= forceDirectionY * scatterSpeed;
        }
        
        // සාමාන්‍ය හෙමින් චලනය වන වේගය එකතු කරනවා
        this.x += this.dx;
        this.y += this.dy;

        this.draw();
      }
    }

    function init() {
      particlesArray = [];
      const divisor = window.innerWidth < 300 ? 20000 : 10000;// Density
      let numberOfParticles = (canvas.height * canvas.width) / divisor;
      
      for (let i = 0; i < numberOfParticles; i++) {
        let size = (Math.random() * 2) + 1;
        let x = Math.random() * innerWidth;
        let y = Math.random() * innerHeight;
        
        // සාමාන්‍ය වේගය (බොහොම හෙමින්)
        let dx = (Math.random() * 1) - 0.5;
        let dy = (Math.random() * 1) - 0.5;
        
        particlesArray.push(new Particle(x, y, dx, dy, size));
      }
    }

    function connect() {
        const connectDistance = window.innerWidth < 768 
            ? (canvas.width / 5) * (canvas.height / 5) 
            : (canvas.width / 9) * (canvas.height / 9);

        for (let a = 0; a < particlesArray.length; a++) {
            for (let b = a; b < particlesArray.length; b++) {
                let distance = ((particlesArray[a].x - particlesArray[b].x) ** 2) + ((particlesArray[a].y - particlesArray[b].y) ** 2);
                
                if (distance < connectDistance) {
                    // Line Color: Gray
                    ctx.strokeStyle = `rgba(100, 100, 100, ${1 - (distance / 20000)})`;
                    ctx.lineWidth = 0.5;
                    ctx.beginPath();
                    ctx.moveTo(particlesArray[a].x, particlesArray[a].y);
                    ctx.lineTo(particlesArray[b].x, particlesArray[b].y);
                    ctx.stroke();
                }
            }
        }
    }

let lastTime = 0;
    const fps = 30; // 60 වෙනුවට 30FPS දාන්න (ඇහැට පේන්නේ නෑ වෙනස)
    const nextFrame = 1000 / fps;

    function animate(currentTime) {
      requestAnimationFrame(animate);

      const deltaTime = currentTime - lastTime;
      if (deltaTime < nextFrame) return; // Skip frame if too fast

      lastTime = currentTime - (deltaTime % nextFrame);

      ctx.clearRect(0, 0, innerWidth, innerHeight);
      for (let i = 0; i < particlesArray.length; i++) {
        particlesArray[i].update();
      }
      connect();
    }
    
    const handleResize = () => {
        canvas.width = window.innerWidth;
        canvas.height = window.innerHeight;
        init();
    }
    window.addEventListener('resize', handleResize);
    return () => window.removeEventListener('resize', handleResize);

  }, []);

  return (
    <canvas 
      ref={canvasRef} 
      style={{ 
        position: 'fixed', 
        top: 0, 
        left: 0, 
        zIndex: 1, 
        pointerEvents: 'none', // සයිට් එකේ ලින්ක්ස් ඔබන්න බාධාවක් වෙන්නේ නෑ
        background: 'transparent' 
      }} 
    />
  );
};