// --- GALLERY IMAGE ---
const GalleryImage = ({ folder, num, onClick }) => {
  const [isVisible, setIsVisible] = useState(true);
  const imgPath = process.env.PUBLIC_URL + `/sample/${folder}/${num}.png`;
  if (!isVisible) return null; 
  return <motion.img src={imgPath} alt={`Gallery ${num}`} className="gallery-img" whileHover={{ scale: 1.05 }} whileTap={{ scale: 0.95 }} onClick={() => onClick(imgPath)} onError={() => setIsVisible(false)} />;
};

