// --- PROJECT MODAL ---
const ProjectModal = ({ project, onClose }) => {
  const [content, setContent] = useState({ desc: "Loading...", features: [], demoLink: "#" });
  const [previewImage, setPreviewImage] = useState(null);

  useEffect(() => {
    if (project) {
      fetch(process.env.PUBLIC_URL + `/sample/${project.folder}/readme.md`)
        .then(res => { if (!res.ok) throw new Error("Failed"); return res.text(); })
        .then(text => {
          const descMatch = text.match(/^#\s+.+\n+([\s\S]*?)(?=\n#|\nFeatures|$)/i);
          const desc = descMatch ? descMatch[1].trim() : "An innovative project.";
          const featureSection = text.match(/Features[\s\S]*?(?=\n#|$)/i);
          const features = featureSection ? featureSection[0].match(/- .+/g)?.map(f => f.replace('- ', '').trim()) : [];
          const linkMatch = text.match(/http[s]?:\/\/[^\s)]+/);
          const demoLink = linkMatch ? linkMatch[0] : "#";
          setContent({ desc, features: features || [], demoLink });
        })
        .catch(() => setContent({ desc: "Details unavailable.", features: [], demoLink: "#" }));
    }
  }, [project]);

  if (!project) return null;

  return (
    <>
      <div className="modal-backdrop" onClick={onClose}>
        <motion.div initial={{ opacity: 0, scale: 0.9, y: 30 }} animate={{ opacity: 1, scale: 1, y: 0 }} exit={{ opacity: 0, scale: 0.9, y: 30 }} className="vision-modal-content" onClick={(e) => e.stopPropagation()}>
          <button className="vision-close-btn" onClick={onClose}><X size={20} /></button>
          <div className="modal-header"><img src={project.image} alt={project.title} className="modal-cover-img" onError={(e) => e.target.style.display='none'} /><div className="modal-gradient-overlay"></div><div className="modal-title-area"><span className="cat-tag-glass">{project.category}</span><h2>{project.title}</h2></div></div>
          <div className="modal-body-grid">
            <div className="modal-section full-width"><h3 className="section-title"><Sparkles size={18}/> About Project</h3><p className="project-desc">{content.desc}</p></div>
            <div className="modal-section full-width"><h3 className="section-title"><Layout size={18}/> Visual Gallery</h3><div className="gallery-grid">{[1, 2, 3, 4, 5].map((num) => (<GalleryImage key={`${project.folder}-${num}`} folder={project.folder} num={num} onClick={setPreviewImage} />))}</div></div>
            <div className="modal-section full-width"><h3 className="section-title"><Cpu size={18}/> Technology Core</h3><div className="tech-chip-container">{project.tech.map((t, i) => (<div key={i} className="tech-chip"><TechIcon name={t}/> <span>{t}</span></div>))}</div></div>
            {content.features.length > 0 && (<div className="modal-section full-width"><h3 className="section-title"><Star size={18}/> Key Features</h3><div className="features-grid">{content.features.map((feat, i) => (<div key={i} className="feature-card"><CheckCircle size={16} color="#00ff88" className="feat-icon" /><span>{feat}</span></div>))}</div></div>)}
            <div className="modal-actions"><a href={content.demoLink} target="_blank" rel="noopener noreferrer" className="action-btn primary"><ExternalLink size={18}/> Live Demo</a><a href="#" className="action-btn secondary"><Github size={18}/> View Code</a></div>
          </div>
        </motion.div>
      </div>
      <AnimatePresence>{previewImage && (<ImagePreview src={previewImage} onClose={() => setPreviewImage(null)} />)}</AnimatePresence>
    </>
  );
};

