import React, { Suspense, useEffect, useState } from 'react';
import { Canvas, useFrame } from '@react-three/fiber';
import { useGLTF, Environment, Float, useTexture } from '@react-three/drei';
import * as THREE from 'three';
import { useIsMobile } from '../hooks/useIsMobile';
import { AdaptiveDpr, AdaptiveEvents, Preload } from '@react-three/drei';

// --- 1. TYPING EFFECT ---
const TypingWaves = () => {
  const [keys, setKeys] = useState([]);
  useFrame((state) => {
    if (state.clock.elapsedTime * 10 % 1 < 0.17) {
      setKeys(prev => [...prev, { id: Math.random(), x: (Math.random() - 0.5) * 13, z: (Math.random() - 0.5) * 1, opacity: 1, scale: 0 }]);
    }
    setKeys(prev => prev.map(k => ({ ...k, opacity: k.opacity - 0.06, scale: k.scale + 0.3 })).filter(k => k.opacity > 0));
  });
  return (
    <group position={[-0.2, -4.9, -1.9]} rotation={[0.23, 0, 0]}>
      {keys.map(key => (
        <mesh key={key.id} position={[key.x, 0, key.z]} rotation={[-Math.PI / 2, 0, 0]} scale={[key.scale, key.scale, 1]}>
          <ringGeometry args={[0.1, 0.33, 32]} />
          <meshBasicMaterial color="#00ff88" transparent opacity={key.opacity} />
        </mesh>
      ))}
    </group>
  );
};

// --- 2. THE UNIFIED MODEL COMPONENT ---
const UnifiedModel = () => {
  const { scene } = useGLTF(`${process.env.PUBLIC_URL}/models/macbook.glb`);
  const screenTexture = useTexture(process.env.PUBLIC_URL +'/vscode.png');
  screenTexture.flipY = false;
  screenTexture.colorSpace = THREE.SRGBColorSpace;

  useEffect(() => {
    scene.traverse((child) => {
      if (child.isMesh) {
        child.material.color.set('#050505');
        child.material.metalness = 0.9;
        child.material.roughness = 0.2;
      }
    });
  }, [scene]);

  return (
    <group>
      <primitive object={scene} scale={61} position={[0, -5.8, 0]} rotation={[0.25, 6.28, 0]} />
      <mesh position={[0, 2.7, -6.4]} rotation={[0, 0, 0]} scale={[18, 11.6, 1]}>
        <planeGeometry />
        <meshStandardMaterial map={screenTexture} roughness={0.2} metalness={0.1} color="#ffffff" />
      </mesh>
      <TypingWaves />
    </group>
  );
};

// --- 3. MAIN CANVAS WITH FINAL SETTINGS ---
export const Laptop3D = () => {
  const isMobile = useIsMobile();

  // --- YOUR FINAL VALUES APPLIED ---
  const config = {
    scale: isMobile ? 0.4 : 0.8, // Mobile: 0.4 | Desktop: 0.1
    position: isMobile ? [-3.8, -2.2, 0] : [0, 2, 0], // Mobile position
    rotation: [0, 0, 0]
  };

  return (
    <Canvas 
      dpr={[1, 1.5]} // ✅ LIMIT PIXEL RATIO (Phone රත් වෙන්නේ නෑ)
      camera={{ position: [0, 2, 35], fov: 35 }}
      gl={{ powerPreference: "high-performance", antialias: false }} // ✅ OPTIMIZATIONS
    >
      {/* 1. Main White Light */}
      <spotLight position={[-20, 48, 36]} intensity={1980} color="#ffffff" angle={0.5} penumbra={1} distance={200} />
      
      {/* 2. Green Rim Light (Updated intensity: 4690) */}
      <spotLight position={[-28, 30, 20]} intensity={4690} color="#9cffd1" distance={200} angle={0.6} penumbra={1} />
      
      {/* 3. Keyboard Area Light (Updated intensity: 34300) */}
      <pointLight position={[-13.6, -1, -17.3]} intensity={34300} color="#00ff88" distance={100} />
      
      <pointLight position={[0, -10, 10]} intensity={20} color="#00ff88" />

      <Suspense fallback={null}>
        <Float speed={5.7} rotationIntensity={0.8} floatIntensity={1.25} floatingRange={[-0.5, 0.5]}>
          <group scale={config.scale} position={config.position} rotation={config.rotation}>
            <UnifiedModel />
          </group>
        </Float>
        <ambientLight intensity={0.1} /> 
        <Environment preset="city" intensity={0.05} />
      </Suspense>
    </Canvas>
  );
};